#include <stdlib.h>

int main() {
    int size;
    scanf("%d", &size);

    if (size > 1000) {  // Prevent too large input
        printf("Size too large.\n");
        return 1;
    }

    int arr[size];
    int freq[size];

    // Initialize frequency array
    for (int i = 0; i < size; i++) {
        freq[i] = 0;
    }

    // Input array
    for (int i = 0; i < size; i++) {
        scanf("%d", &arr[i]);
        if (arr[i] >= 0 && arr[i] < size) {
            freq[arr[i]]++;
        }
    }

    // Find missing and duplicate numbers
    printf("Missing numbers: ");
    for (int i = 0; i < size; i++) {
        if (freq[i] == 0) {
            printf("%d ", i);
        }
    }

    printf("\nDuplicate numbers: ");
    for (int i = 0; i < size; i++) {
        if (freq[i] > 1) {
            printf("%d ", i);
        }
    }

    return 0;
}
